media_type.script:

var params = JSON.parse(value);
var n8nUrl = params.n8n_url;

var payload = {
    host:         '{HOST.NAME}',
    ip:           '{HOST.IP}',
    trigger_name: '{TRIGGER.NAME}',
    trigger_id:   '{TRIGGER.ID}',
    service_name: '{ITEM.KEY1}',
    event_id:     '{EVENT.ID}',
    event_type:   '{EVENT.STATUS}',
    severity:     '{TRIGGER.SEVERITY}',
    timestamp:    '{EVENT.DATE} {EVENT.TIME}',
    event_tags:   '{EVENT.TAGSJSON}'
};

var req = new HttpRequest();
req.addHeader('Content-Type: application/json');

var response = req.post(n8nUrl, JSON.stringify(payload));

if (req.getStatus() !== 200) {
    throw 'n8n webhook falhou: HTTP ' + req.getStatus() + ' — ' + response;
}

return 'OK: ' + response;

message_template.message:
Host: {HOST.NAME} ({HOST.IP})
Trigger: {TRIGGER.NAME}
Serviço: {ITEM.KEY1}
Severidade: {TRIGGER.SEVERITY}
Hora: {EVENT.DATE} {EVENT.TIME}
ID do Evento: {EVENT.ID}

Host: {HOST.NAME} ({HOST.IP})
Trigger: {TRIGGER.NAME}
Serviço: {ITEM.KEY1}
Recuperado em: {EVENT.RECOVERY.DATE} {EVENT.RECOVERY.TIME}
Duração: {EVENT.DURATION}
